// Package runner implements three runner_work_v1 JetStream durables, each with
// a bounded worker pool mirroring
// internal/ingest.JobsConsumer's hand-rolled `cons.Consume` + sem/wg shape
// (NOT internal/githubpr's serial jsconsumer.Start pattern): runner work is
// bursty and long-running (design doc's D-9 dedicated-deployment rationale),
// so one pod must drain several provision/prompt/poll messages in parallel
// rather than one at a time.
//
// The split itself is not a style choice: prompt/snapshot have bounded broker
// delivery, while provision and poll have unlimited broker delivery for durable
// ownership coordination and self-perpetuating polling respectively. Genuine
// provision failures still use the application's workMaxDeliver budget. A JetStream
// WorkQueue stream rejects two consumers whose filter subjects overlap, so
// one consumer could never serve both delivery policies anyway (design doc
// §1, D-C1-a).
//
// C.1.2 SCOPE: the real provision→prompt→poll state machine lives in
// handlers.go (handleProvision/handlePrompt/handlePollDecoded/handleSnapshot)
// — this file keeps the worker-pool plumbing, the three durables' delivery-
// policy split, the msg.InProgress heartbeat, the decode→dispatch preamble,
// and the dead-letter call path. snapshot stays a no-op-Ack stub (C.5 owns
// result writes).
package runner

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"maps"
	"runtime/debug"
	"slices"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"golang.org/x/sync/errgroup"

	"github.com/entireio/go-nuts/backoff"
	"strings"

	"github.com/entireio/go-nuts/jsconsumer"
	"github.com/entireio/go-nuts/natsmsg"

	"github.com/entirehq/entire-api/internal/config"
	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entirehq/entire-api/internal/reviewpublish"
	"github.com/entirehq/entire-api/internal/runnerissuer"
	"github.com/entirehq/entire-api/internal/sandbox"
	"github.com/entirehq/entire-api/internal/store"
)

const (
	// These are the three durable consumer names on runner_work_v1, stable
	// across restarts. Cell-local: subjects are
	// repo-scoped only (SubjectPrefix's doc), no jurisdiction token, so one
	// durable per cell serves every repo the cell owns.
	provisionDurable = "runner-provision-consumer"
	workDurable      = "runner-work-consumer"
	pollDurable      = "runner-poll-consumer"

	// ackWait is shared by all durables: 30s, matching the ingest/githubpr
	// consumers' house default — comfortably longer than a provider RPC + a
	// store write, short enough that a stuck message redelivers promptly. The
	// msg.InProgress heartbeat (natsmsg.KeepInProgress, in decodeAndDispatch)
	// extends this for a handler that legitimately runs long (a slow provider
	// call).
	ackWait = 30 * time.Second

	// workMaxDeliver caps redelivery of a bounded-attempt job before it's
	// poison and gets dead-lettered: the BFF's run attempt cap (4) plus a
	// margin for a transient redelivery, per the design doc's table.
	// retryUnconfirmedProvision retries inline, once, outside this budget: it
	// holds the provisioning claim, so a nak would only defer until the claim
	// went stale. Retuning this number does not affect it.
	workMaxDeliver = 5

	// pollMaxDeliver is JetStream's "redeliver forever" sentinel: poll is
	// self-perpetuating by design (D-C1-e, decision B) — a still-running
	// detached exec re-arms itself via NakWithDelay every cadence tick, and
	// only a handler-checked wall-clock deadline (C.1.2), never a delivery
	// count, ends the loop.
	pollMaxDeliver = -1

	// provisionMaxDeliver is the same "redeliver forever" sentinel for a
	// completely different reason (ENT-1644): a provision redelivery that finds
	// the run already claimed is COORDINATION, not a failed attempt, so it must
	// not spend a poison budget waiting for the owner. Genuine pre-claim
	// failures still give up at workMaxDeliver, which the handler checks
	// itself (backoff.IsFinalDelivery). Spelled separately from pollMaxDeliver
	// so retuning either policy cannot silently move the other.
	provisionMaxDeliver = -1

	// DefaultConcurrency is the worker-pool size when the RUNNER_WORKER_CONCURRENCY
	// env is unset/non-positive — see effectiveConcurrency. Lower than the
	// index-jobs consumer's default (16): this is a dedicated, bursty,
	// long-poll-heavy deployment (design doc D-9), not the product-critical
	// index pipeline, and a real provider call (C.1.2) is far heavier per
	// unit of work than a commit-walk page.
	DefaultConcurrency = 8

	// maxAckPending is each durable's in-flight ceiling: one budget shared by
	// every pod on the durable, so it covers all of them at once. Per-pod pacing
	// is jsconsumer.Config.MaxMessages. Headroom rather than a tuning knob —
	// RUNNER_WORKER_CONCURRENCY is the knob.
	maxAckPending = 256

	// defaultPollInterval is the poll handler's re-poll cadence (D-C1-e,
	// decision B): how long a still-running detached exec's poll message
	// waits (NakWithDelay) before the poll durable redelivers it for another
	// PollDetachedExec call. Not yet config-surfaced — a future phase can
	// promote this to a RunnerConfig field if per-cell tuning turns out to
	// matter; tests override Consumer.pollInterval directly.
	defaultPollInterval = 5 * time.Second

	// cappedRepollDelay replaces pollInterval after a poll that set More. It
	// is not zero so a chatty agent cannot hold a poll worker in a tight loop.
	cappedRepollDelay = 250 * time.Millisecond

	// exitedDrainGrace is how long past deadline_at the poll handler keeps
	// draining an Exited command's log. It stays under sandboxLifetimeGrace
	// and runnerreaper.DefaultDeadlineGrace, so the sandbox outlives the drain.
	exitedDrainGrace = time.Minute

	// defaultRunTimeout bounds a run's ENTIRE detached-exec attempt (D-C1-e's
	// wall-clock deadline, computed once by the prompt handler as
	// now+runTimeout and persisted to deadline_at): the poll handler fails the
	// run out from under it once now() passes this deadline, regardless of
	// how many re-polls that took. Repo-authored runs may select a shorter
	// persisted timeout; this remains the fallback and hard maximum.
	defaultRunTimeout = MaxAgentTimeout

	// MaxAgentTimeout is the largest repo-authored per-run deadline. It is
	// shared with launchRun validation, which rejects any persisted timeout
	// past this ceiling.
	MaxAgentTimeout = 30 * time.Minute

	// Allow final output reads without renewing forever when terminal writes fail.
	sandboxLifetimeGrace = 2 * time.Minute

	// MaxBrokerCredentialLifetime is the longest admission can keep letting a
	// run call: it checks broker_credential_expires_at, not MaxAgentTimeout.
	// Exported as the ceiling on the broker's run-key cache TTL.
	// TestBrokerCredentialLifetimeMatchesMint fails if this and the mint drift.
	MaxBrokerCredentialLifetime = provisionExecutionTimeout + MaxAgentTimeout + assertionExpiryGrace

	// assertionExpiryGrace is the margin MaxBrokerCredentialLifetime adds on
	// top of provisioning plus the run itself, so brokered calls keep working
	// through a run's teardown after its deadline passes. The runner
	// assertion does not use this value; see runnerAssertionLifetime for that.
	assertionExpiryGrace = 10 * time.Minute

	// runnerAssertionLifetime bounds the provision-time automation assertion.
	// mintRunnerAssertion exchanges it for a runner token and discards it
	// before ClaimRunProvision or Provision run, so its lifetime only needs
	// to cover that exchange, not the run: prod's exchange latency
	// (runner.automation.exchange_latency_ms, provision path, n≈9,882) puts
	// p99 at 327ms and the max at 830ms. 5m matches trailBodyAssertionLifetime,
	// the same mint-exchange-discard shape, and stays independent of
	// MaxAgentTimeout and provisionExecutionTimeout on purpose.
	runnerAssertionLifetime = 5 * time.Minute

	// automationMissingRetryDelay is the cadence for the narrow safety net
	// between a provision delivery observing a missing automation and the
	// repo-activity reconciler making it visible. Each wait refreshes the run's
	// guarded updated_at so the reaper's configurable five-minute floor cannot
	// race an equally long retry window.
	automationMissingRetryDelay  = 15 * time.Second
	automationMissingRetryWindow = 5 * time.Minute
)

// effectiveConcurrency resolves the worker-pool size from a configured value,
// falling back to DefaultConcurrency when non-positive — mirrors
// ingest.EffectiveConcurrency so ops tuning follows the same house
// convention (0/unset means "use the default", not "zero workers").
func effectiveConcurrency(n int) int {
	if n <= 0 {
		return DefaultConcurrency
	}
	return n
}

// filterSubject builds the wildcard-repo filter subject for one WorkKind:
// runner_work_v1.*.<kind> — every repo this cell owns, one specific kind.
func filterSubject(kind WorkKind) string {
	return SubjectPrefix + ".*." + string(kind)
}

// Provision has an unlimited broker delivery budget because rejected durable
// claims are coordination, not failed attempts. The handler still terminalizes
// genuine pre-claim failures at workMaxDeliver.
var provisionFilterSubjects = []string{filterSubject(WorkKindProvision)}

// Prompt and snapshot retain the bounded poison-message budget.
var workFilterSubjects = []string{
	filterSubject(WorkKindPrompt),
	filterSubject(WorkKindSnapshot),
}

// pollFilterSubjects is the runner-poll-consumer's filter set: poll alone,
// isolated onto its own durable with independent flow control.
var pollFilterSubjects = []string{filterSubject(WorkKindPoll)}

// Dead-letter reasons for runner_work_v1 poison messages. Mirrors
// internal/jobsdlq's Reason* vocabulary, but on a DIFFERENT stream
// (runner_work_dlq_v1, not repo_jobs_dlq_v1 — the design doc's §1 "don't
// overload repo_jobs_dlq_v1"), so it can't reuse that package's Subject/
// StreamName, which are hardcoded to the shared jobs DLQ.
//
// IMPORTANT — deployment prerequisite: runner_work_dlq_v1 is provisioned
// declaratively in fleet by Phase C.1.0, NOT by this binary. A cell must NOT
// flip CONSUME_RUNNER_WORK on before that stream exists there — otherwise
// every dead-letter publish fails (deadLetter's Nak fallback keeps poison
// parked rather than dropping it, but it never actually reaches the DLQ).
//
// Also note: as of Phase C.1.3a, an ORDINARY exhausted redelivery (a
// bounded-attempt handler's own transient-error path, e.g. a store blip or an
// unclassified provider error, still failing on the work durable's LAST
// allowed delivery) is now caught in-band ON THE HAPPY PATH — see handlers.go's
// nakBackoffOrFail/backoff.IsFinalDelivery, which escalate to a terminal
// `failed` run + dead-letter instead of nak-ing into a redelivery JetStream
// would otherwise silently never send.
//
// That guarantee is WEAKER than "always", and this package should not be read
// as claiming otherwise (a PR review on this exact phase caught an earlier,
// over-confident version of this paragraph): the escalation's own terminal
// write (failRunWithRetry, handlers.go) depends on the SAME run store the
// original error may itself be reporting as unhealthy. failRunWithRetry
// retries that ONE write a few times inline specifically to cover a
// short-lived blip at exactly this moment, but if the store stays down for
// the whole retry window, the guarantee degrades to "a DLQ entry exists" —
// an operator can see the poison message and its reason, but the run itself
// is NOT visibly `failed`; it stays at whatever non-terminal status it was
// in. Phase C.1.3b's reaper is the explicit, NAMED backstop for that residual
// gap, not just for the redelivery-timeout case below: it must sweep every
// non-terminal status (creating/ready/prompting, not only creating) by
// updated_at, since this gap and the crash-mid-handler gap both leave a
// non-terminal row with a stale updated_at and no further in-band chance to
// self-correct.
//
// What is UNCONDITIONALLY unswept, and still needs Phase C.1.3b's
// MAX_DELIVERIES advisory reaper (internal/jobsdlq's pattern, ported for this
// stream) regardless of store health: a message that exhausts its delivery
// budget via redelivery TIMEOUT rather than an in-handler disposition — a pod
// crash (or an ungraceful kill) mid-handler, after AckWait lapses enough
// times with no terminal Ack/Nak/dead-letter ever sent for that specific
// delivery. That case never re-enters any handler logic at all, so nothing
// in this package can notice it; it parks on runner_work_v1 until C.1.3b's
// reaper sweeps stale non-terminal runs by updated_at.
//
// Also unswept by anything in THIS package (see handlePollDecoded's own doc
// for the full enumeration): several poll-durable failure modes have no
// delivery-count OR deadline backstop at all (a GetRun error before
// rec.DeadlineAt is even readable; a terminal write that keeps failing;
// timeoutRun's own write failure) — poll's unbounded MaxDeliver=-1
// means these nak-loop forever, not just until a budget runs out. Named as an
// explicit C.1.3b requirement, not fixed here.
const (
	// DLQStreamName is the dead-letter stream for runner_work_v1, provisioned
	// declaratively in fleet by Phase C.1.0 (NOT created by this binary). A
	// dead-letter publish against a not-yet-provisioned stream fails — safe
	// today because RUNNER_MACHINE_ENABLED/CONSUME_RUNNER_WORK are both
	// default-false, so no cell reaches this path before C.1.0 lands there.
	DLQStreamName = "runner_work_dlq_v1"
	// dlqSubjectPrefix + <reason> composes the dead-letter subject.
	dlqSubjectPrefix = "runner.work.dlq.v1."
	// ReasonDecode covers everything contract.go's Unmarshal rejects today: an
	// unmarshalable payload, trailing data after one JSON value, a missing/zero
	// schema_version, or an unrecognized WorkKind — Unmarshal doesn't
	// distinguish these from each other (see its doc comment's
	// versioning-policy paragraph), so neither does this. A SchemaVersion
	// newer than CurrentSchemaVersion is deliberately NOT one of them:
	// Unmarshal doesn't check for that today — see contract.go's doc for why
	// (deferred to the eventual v2-stream cutover, not an in-place check).
	ReasonDecode = "decode"
	// ReasonPanic marks a message dead-lettered because its handler panicked
	// (see runDurable's recover) — not a decode problem, a runtime one, most
	// likely from a provider SDK/network call once C.1.2 adds those.
	ReasonPanic = "panic"
	// ReasonUnexpectedKind marks handleWork's defensive default case: a
	// decoded WorkKind that Unmarshal accepted (so it's in contract.go's
	// closed set) but that workFilterSubjects should never actually route
	// here (only provision/prompt/snapshot are). Unreachable in production —
	// the filter subjects and Unmarshal's Valid() check both already prevent
	// it — but distinct from ReasonDecode so a DLQ inspector isn't misled
	// into thinking the payload itself was malformed.
	ReasonUnexpectedKind = "unexpected_kind"
)

// dlqSubject builds the dead-letter subject for a poison runner_work_v1
// message, tagged by reason.
func dlqSubject(reason string) string {
	return dlqSubjectPrefix + natsmsg.SubjectToken(reason)
}

// RunReader is the store read surface every C.1.2 handler precondition-gates
// its transition on (design doc's D-C1-b: "every handler re-reads
// sandbox_runs.status via a new GetRun and no-ops if the run already
// advanced"), widened by Phase C.2.3a with the repo-metadata reads a fresh
// provision resolves its real request content from (design doc §3).
type RunReader interface {
	GetRun(ctx context.Context, id string) (store.RunRecord, bool, error)
	RunUsageForTerminal(ctx context.Context, id string) (store.TerminalRunUsage, bool, error)

	// CountActiveRuns reports the cell's in-flight runs by status and
	// provider, for the runner.runs.active gauge (saturation.go). Cell-wide,
	// so every pod's answer is the same one.
	CountActiveRuns(ctx context.Context) ([]store.ActiveRunCount, error)

	// RunRepoAndTrail resolves runID's repo/trail identity — terminalRun's
	// source for the findings-gate recompute hook on a failed/timed-out
	// review run (ENT-1618). See the store method's own doc for why this is
	// its own narrow read rather than a field added to RunRecord or
	// AdmitTerminalRun's return.
	RunRepoAndTrail(ctx context.Context, runID string) (repoID string, trailID *string, ok bool, err error)

	// GitHubFullName resolves the owner/repo name only for the legacy
	// github.com fallback. EntireDB provisioning addresses RepoID directly.
	GitHubFullName(ctx context.Context, repoID string) (string, error)

	// IsMirrorRepo distinguishes a GitHub mirror from a native repository
	// whose path-derived full name can look like "owner/repo". It protects
	// the legacy github.com fallback; EntireDB provisioning addresses RepoID.
	IsMirrorRepo(ctx context.Context, repoID string) (bool, error)

	// DefaultBranch resolves a repo's stored default branch ref (e.g.
	// "refs/heads/main"), ok=false if unresolved (store/store.go — already
	// exists). resolveRef's fallback when a run has no usable HeadSha: a
	// plain, unpinned branch ref that git resolves to its true tip at fetch
	// time (see resolveRef's doc for why this beats resolving a sha
	// server-side from a mirror read).
	DefaultBranch(ctx context.Context, repoID string) (string, bool, error)

	// RunTrailBase resolves a trail-scoped run's base branch (ok=false for a
	// run with no trail), which handleProvision passes to
	// sandbox.ProvisionRequest.BaseRef. Best-effort — see that field's doc.
	RunTrailBase(ctx context.Context, repoID, runID string) (string, bool, error)

	// RepoGroupIDs resolves placement repo ids to their repo_group ULIDs. A
	// repo id absent from the returned map is not a store error.
	RepoGroupIDs(ctx context.Context, repoIDs []string) (map[string]string, error)

	// RepoClusterSlug reports the repo's entiredb cluster; "" means not
	// knowable — see ReasonEntireDBHostUnknown, the refusal an empty slug
	// triggers at provision time.
	RepoClusterSlug(ctx context.Context, repoID string) (string, error)

	// EditorDocumentByID resolves a trail's linked body document to its real
	// DocumentKey for the trail-body write — see resolveTrailBodyDocumentKey
	// (trailbody.go) for why the deterministic key alone is not enough.
	EditorDocumentByID(ctx context.Context, id string) (store.EditorDocument, bool, error)
}

// RunWriter is the store write surface every C.1.2 handler persists its
// transition through.
type RunWriter interface {
	ClaimRunProvision(ctx context.Context, runID string, now time.Time) (bool, error)
	AdmitProvisionAttempt(ctx context.Context, runID string, provider sandbox.ProviderID, claimedAt time.Time) (store.ProvisionAttempt, bool, error)
	CancelProvisionAdmission(ctx context.Context, runID string, claimedAt, now time.Time) (bool, error)
	AbandonProvisionAttempt(ctx context.Context, runID, attemptID string, environmentID sandbox.EnvironmentID, now time.Time) (bool, error)
	SelectProvisionAttempt(ctx context.Context, runID, attemptID string, environmentID sandbox.EnvironmentID, now time.Time) (bool, error)
	RecoverStaleProvisionAttempt(ctx context.Context, runID string, provisionStartedAt time.Time, now time.Time) (store.ProvisionAttempt, bool, error)
	FailProvisionAttempt(ctx context.Context, runID, attemptID string, environmentID sandbox.EnvironmentID, reason string, now time.Time) (bool, error)
	// RecordProvisionProvider names the provider the active claim is about to
	// call. Best-effort at the call site; see the store method.
	RecordProvisionProvider(ctx context.Context, runID string, provider sandbox.ProviderID, now time.Time) (bool, error)
	// ReleaseRunProvision clears an unattached provisioning claim so a
	// redelivery can re-provision (handleProvision's retryable clone/checkout
	// path). Refuses once an environment is attached; see the store method.
	ReleaseRunProvision(ctx context.Context, runID string, now time.Time) (bool, error)
	TouchRunAwaitingProvision(ctx context.Context, runID string, now time.Time) (bool, error)
	AttachRunProvisionEnvironment(ctx context.Context, runID string, environmentID sandbox.EnvironmentID, provider sandbox.ProviderID, now time.Time) (bool, error)
	// RecordRunCheckedOutSha stores the commit provisioning resolved
	// (ENT-1657). Opportunistic: a false or an error must not fail the run.
	RecordRunCheckedOutSha(ctx context.Context, runID, sha string, now time.Time) (bool, error)
	// RecordRunResources is measurement only; an error never fails the poll.
	RecordRunResources(ctx context.Context, runID string, r sandbox.SandboxResources, final bool) error
	CompleteRunProvision(ctx context.Context, runID string, environmentID sandbox.EnvironmentID, workdir string, now time.Time) (bool, error)
	FailStaleRunProvision(ctx context.Context, runID string, provisionStartedAt time.Time, environmentID sandbox.EnvironmentID, reason string, now time.Time) (bool, error)

	// UpsertRunWithResult reports whether the prompt transition committed.
	// Provision ownership and completion use the narrow guarded methods above;
	// prompt still persists an exec_session_id that nothing else records.
	//
	// There is deliberately no plain UpsertRun here. It discards that signal,
	// and this package no longer has a caller for which losing a write silently
	// is acceptable — terminal writes went to AdmitTerminalRun (ENT-1397) and
	// these two to the variant above. Keeping it on the interface would advertise
	// a write mode the package does not use.
	UpsertRunWithResult(ctx context.Context, in store.UpsertRunInput) (store.UpsertRunResult, error)
	// Must be called BEFORE terminalizing a run — it is guarded on
	// status = 'prompting'. See the store method's doc.
	AppendRunEvents(ctx context.Context, in store.AppendRunEventsInput) (store.AppendRunEventsResult, error)
	GetRunCompletion(ctx context.Context, runID string) (store.RunCompletion, bool, error)
	CompleteRunWithResult(ctx context.Context, in store.CompleteRunWithResultInput) (store.CompleteRunWithResultResult, error)
	// RecordCorrectionTurn banks one resumed turn's output and cost
	// (correction.go). Bookkeeping for work already done, so a failure here
	// does not cost the caller its corrected result.

// Package jsconsumer is the durable JetStream pull-consumer scaffold shared by
// Entire's decode-and-dispatch consumers. Each of those used to hand-roll the
// same lifecycle: jetstream.New → CreateOrUpdateConsumer (durable, explicit
// ack, bounded ack-wait, bounded MaxDeliver, filter subject) → Consume → stop
// on context cancel; and the same per-message prologue: open a consumer span
// (re-parented across the NATS hop), decode the payload, and Term on a decode
// error.
//
// This package owns exactly that scaffold and nothing else. Each consumer
// keeps its OWN event type, business dispatch, metrics, and log lines — Start
// takes the consumer's message callback, and Process invokes the consumer's
// handle with the decoded event and the live span. The handler owns the
// message's terminal disposition (Ack/Nak/Term); Process never touches a
// message that decoded.
//
// The one exception to "disposition stays with the handler" is [Retry], the
// scaffold's optional single retry mechanism: the redelivery ladder and the
// dead-letter capture it terminates into (ENT-1535). A handler that
// configures one calls [Retry.Settle] instead of picking a disposition
// itself. The consumer has exactly one redelivery scheduler and it is the
// SERVER's: the durable's BackOff ladder, or its AckWait when no ladder is
// set. Retry disposes of nothing on the retry path, so that schedule is the
// one that runs — see [Retry] for why a plain Nak would skip it entirely.
//
// [FloorMonitor] is the separate, advisory half: it polls the durable's ack
// floor and reports how long it has been stalled. Hand it to a Retry and it
// becomes the floor-age circuit breaker — which does NOT identify the message
// pinning the floor, because consumer info does not carry that: it acts on a
// conjunction of independently true facts, so it may quarantine a message that
// was failing alongside the blocker rather than being it (bounded to one per
// stall window, and the copy is replayable — see [Retry]). Use the monitor
// alone and it is just the health signal, leaving the quarantine decision to
// the adopter.
//
// Lifted from entire-api's internal/jsconsumer (COR-929), folding in the
// module's shutdown classification ([nuts.IsShutdownFetchErr] gates the
// consume-error log so a drain during rollout isn't reported as a fault,
// COR-923) and an optional [natsmsg.KeepInProgress] heartbeat for consumers
// whose handlers legitimately outrun AckWait.
package jsconsumer

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entireio/go-nuts"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	// DefaultAckWait is how long JetStream waits for an ack before redelivery
	// when Config.AckWait is zero — comfortably longer than an RPC round-trip
	// plus a DB upsert, short enough that a stuck message redelivers promptly.
	DefaultAckWait = 30 * time.Second
	// DefaultMaxDeliver caps redelivery before JetStream stops redelivering a
	// message when Config.MaxDeliver is zero.
	DefaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its
// existing on-server filter form exactly.
type Config struct {
	Stream         string        // JetStream stream to bind (must already exist)
	Durable        string        // durable consumer name, stable across restarts
	FilterSubject  string        // set this OR FilterSubjects
	FilterSubjects []string      // set this OR FilterSubject
	AckWait        time.Duration // 0 → DefaultAckWait (see EffectiveAckWait)
	MaxDeliver     int           // 0 → DefaultMaxDeliver (see EffectiveMaxDeliver)
	SpanName       string        // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string        // short consumer name, used as the log prefix

	// InactiveThreshold mirrors jetstream.ConsumerConfig.InactiveThreshold:
	// how long the durable may go without an active subscription before the
	// server deletes it; zero means never (the JetStream default for
	// durables) UNLESS the stream sets ConsumerLimits.InactiveThreshold — see
	// the note below. Consumers on interest-retention streams set this so a
	// decommissioned durable stops pinning every message it would have
	// received, instead of holding them until the stream's MaxAge.
	InactiveThreshold time.Duration

	// MaxAckPending mirrors jetstream.ConsumerConfig.MaxAckPending: the
	// server-side cap on deliveries outstanding un-acked across ALL replicas
	// sharing the durable; zero uses the server default (1000), or the stream's
	// ConsumerLimits.MaxAckPending when it sets one — see the note below.
	// Distinct from MaxMessages below, which caps only this process's
	// client-side buffer.
	//
	// # Stream ConsumerLimits fill in both zeros
	//
	// A stream may carry ConsumerLimits, and the server applies them to any
	// consumer that left the matching field zero. So on such a stream neither
	// zero above means what it says: this scaffold's consumers inherit the
	// STREAM's MaxAckPending instead of 1000, and — the consequential one — an
	// InactiveThreshold instead of never, which gives the durable a deletion
	// timer nobody here asked for. A durable deleted that way is recreated from
	// the stream's DeliverPolicy (all, by default) and replays the retained
	// backlog, so the cost of the surprise is a replay, not just a gap.
	//
	// Set both explicitly on a stream with ConsumerLimits, and read the
	// durable's STORED config rather than assuming either field above is what is
	// running. Requests that leave them unset are also what pedantic-mode
	// clients reject outright (NACK's controller drives fleet Consumer CRs that
	// way), so a config this scaffold applies quietly can fail to reconcile in
	// the cluster. Measured in internal/brokersemantics
	// (TestStreamConsumerLimitsAreInheritedBySilentConsumers).
	MaxAckPending int

	// BackOff mirrors jetstream.ConsumerConfig.BackOff: the redelivery
	// ladder, one delay per redelivery, applied in place of AckWait. The
	// server owns redelivery — this is the one schedule, and [Retry] defers to
	// it by leaving a failed delivery untouched rather than running a
	// competing one client-side. JetStream
	// repeats the last rung once the array runs out, so a short list under a
	// larger MaxDeliver is not a short ladder.
	//
	// Setting it alongside Retry is the intended combination. Its coherence —
	// total time to the dead-letter branch, agreement with AckWait, rung count
	// against MaxDeliver — is checked at Start through [Schedule], the same
	// function fleet CI runs over a rendered NACK Consumer CR.
	//
	// Leaving it nil is a choice, not a default: the broker still redelivers,
	// on AckWait, so the effective ladder becomes AckWait repeated up to
	// MaxDeliver. [Schedule] models it that way and holds it to the same
	// bounds, which is usually how an unset BackOff gets caught — an AckWait
	// sized for one RPC makes a fast, tight retry loop, and one sized for a
	// slow handler makes a very long one.
	//
	// Start always sends this value to CreateOrUpdateConsumer, so a nil also
	// CLEARS any ladder already on the durable. A consumer whose ladder is
	// managed declaratively therefore cannot just omit it here — that erases
	// the managed ladder on every start. Declarative management needs a
	// bind-only mode that skips consumer creation, which does not exist yet;
	// until it does, the app states the ladder here.
	BackOff []time.Duration

	// Retry is where this consumer's retries END: dead-letter capture, then
	// settle, plus — when its RetryConfig names a FloorMonitor — the
	// experimental floor-age circuit breaker. It does NOT schedule
	// redelivery; BackOff above does. When set, [Process] dead-letters an
	// undecodable payload instead of Terming it, and the whole schedule
	// (ladder, AckWait, MaxDeliver, and this Retry's expectations of them) is
	// validated together at Start. Its MaxDeliver must equal
	// EffectiveMaxDeliver().
	//
	// Handlers reach it through the closure they build, and call
	// [Retry.Settle] as their one disposition for a failed delivery. Nil
	// leaves disposition entirely to the handler, as before.
	Retry *Retry

	// FloorMonitor runs the durable's ack-floor health signal: [Start] polls
	// it and [Runner.Stop] joins that poll. Set it to publish the stall as a
	// gauge, or to drive a quarantine rule of your own, without adopting the
	// library's automatic breaker.
	//
	// Leave it nil when Retry already carries the monitor — Start uses that
	// one. Naming two different monitors is a Start error: one durable has one
	// ack floor, and one poll loop should read it.
	FloorMonitor *FloorMonitor

	// Tracer opens the per-message consumer span; nil uses the global OTel
	// tracer provider.
	Tracer trace.Tracer
	// Logger receives the scaffold's own log lines (decode-term warnings,
	// consume errors); nil uses slog.Default.
	Logger *slog.Logger

	// KeepInProgress runs a natsmsg.KeepInProgress heartbeat while handle
	// executes, for handlers that legitimately outrun AckWait. The extension
	// is capped, so a wedged handler still redelivers — see
	// natsmsg.KeepInProgress. The heartbeat stops when handle returns; a tick
	// racing the handler's own terminal Ack/Nak/Term is a client-side no-op
	// (nats.go marks the message disposed locally) that halts the heartbeat.
	//
	// Setting this forces the prefetch to one message (see MaxMessages): the
	// heartbeat extends only the delivery the handler holds, so anything
	// buffered behind a long handler would exhaust its AckWait unextended.
	KeepInProgress bool

	// MaxMessages caps how many deliveries the consume loop buffers
	// client-side (jetstream.PullMaxMessages); 0 uses the nats.go default
	// (500). AckWait runs from server delivery into that buffer, not from
	// callback dispatch, and callbacks run serially — so a consumer whose
	// handler can approach AckWait should keep this small or queued
	// deliveries expire and redeliver concurrently to other replicas.
	// KeepInProgress forces it to 1; setting both to conflicting values is a
	// Start error.
	MaxMessages int
}

// EffectiveAckWait is the AckWait actually applied to the JetStream consumer:
// Config.AckWait, or DefaultAckWait when zero. Use it — not the raw field —
// anywhere the real value matters, e.g. wiring a natsmsg.KeepInProgress
// heartbeat by hand (a zero ackWait there is a no-op).
func (c Config) EffectiveAckWait() time.Duration {
	if c.AckWait == 0 {
		return DefaultAckWait
	}
	return c.AckWait
}

// EffectiveMaxDeliver is the MaxDeliver actually applied to the JetStream
// consumer: Config.MaxDeliver, or DefaultMaxDeliver when zero. Use it — not
// the raw field — when building a backoff.Policy for this consumer's
// messages: the two packages read zero differently (here it means "default
// to DefaultMaxDeliver"; on the policy it means unlimited redeliveries, the
// jetstream.ConsumerConfig semantics), so passing a zero Config.MaxDeliver
// through verbatim would make TermOnExhaustion never fire on the broker's
// real final delivery and orphan work-queue messages (COR-762).
func (c Config) EffectiveMaxDeliver() int {
	if c.MaxDeliver == 0 {
		return DefaultMaxDeliver
	}
	return c.MaxDeliver
}

// validate rejects the configuration errors no retry can fix; shared by
// [Start] (one-shot) and [Run] (supervised, which must fail fast on these
// rather than retry them forever).
func (c Config) validate(nc *nats.Conn, onMsg func(jetstream.Msg)) error {
	if c.KeepInProgress && c.MaxMessages > 1 {
		return fmt.Errorf("jsconsumer(%s): KeepInProgress requires MaxMessages <= 1: the heartbeat extends only the in-flight delivery, so %d buffered messages would exhaust AckWait behind a long handler", c.Name, c.MaxMessages)
	}
	if c.Stream == "" {
		return fmt.Errorf("jsconsumer(%s): Stream is required", c.Name)
	}
	if c.Durable == "" {
		// CreateOrUpdateConsumer accepts an empty durable and silently makes
		// an ephemeral, server-named consumer — losing the stable
		// resume-across-restarts behavior this scaffold promises.
		return fmt.Errorf("jsconsumer(%s): Durable is required", c.Name)
	}
	if onMsg == nil {
		return fmt.Errorf("jsconsumer(%s): onMsg is required", c.Name)
	}
	if c.FilterSubject != "" && len(c.FilterSubjects) != 0 {
		return fmt.Errorf("jsconsumer(%s): set FilterSubject or FilterSubjects, not both", c.Name)
	}
	for i, subject := range c.FilterSubjects {
		if subject == "" {
			return fmt.Errorf("jsconsumer(%s): FilterSubjects[%d] is empty", c.Name, i)
		}
	}
	if c.AckWait < 0 {
		return fmt.Errorf("jsconsumer(%s): AckWait must not be negative", c.Name)
	}
	if c.MaxDeliver < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxDeliver must be -1 (unlimited), 0 (default), or positive", c.Name)
	}
	if c.MaxMessages < 0 {
		return fmt.Errorf("jsconsumer(%s): MaxMessages must not be negative", c.Name)
	}
	if c.MaxAckPending < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxAckPending must be -1 (unlimited), 0 (server or stream ConsumerLimits default), or positive", c.Name)
	}
	if c.InactiveThreshold < 0 {
		return fmt.Errorf("jsconsumer(%s): InactiveThreshold must not be negative", c.Name)
	}
	if c.FloorMonitor != nil && c.Retry != nil && c.Retry.Monitor() != nil && c.FloorMonitor != c.Retry.Monitor() {
		return fmt.Errorf("jsconsumer(%s): %w", c.Name, errMonitorConflict)
	}
	if c.Retry != nil && c.Retry.MaxDeliver() != c.EffectiveMaxDeliver() {
		// A policy that disagrees with the broker either never reaches its
		// terminal branch or reaches it early (COR-762) — and with Retry the
		// terminal branch is the DLQ capture, so the disagreement is a lost
		// message rather than a late one.
		return fmt.Errorf("jsconsumer(%s): Retry MaxDeliver is %d but the consumer's is %d: they must match or the dead-letter branch misses the broker's final delivery", c.Name, c.Retry.MaxDeliver(), c.EffectiveMaxDeliver())
	}
	// The whole retry schedule — the server's ladder plus whatever the Retry
	// expects of it — is checked in one place, by the same function fleet CI
	// runs over a rendered Consumer CR and a future bind-only mode will run
	// against the durable's live config. See [Schedule].
	//
	// Only for a consumer that opted into one of them. A durable that carries
	// neither a Retry nor a ladder has nothing here to be coherent about, and
	// must not acquire a new way to fail at startup because this package grew
	// a validator. It runs AFTER the cross-check above so a genuine
	// MaxDeliver mismatch reports as itself rather than as generic
	// incoherence.
	if c.Retry != nil || len(c.BackOff) > 0 {
		if err := c.schedule().Err(); err != nil {
			return fmt.Errorf("jsconsumer(%s): %w", c.Name, err)
		}
	}
	if nc == nil {
		return fmt.Errorf("jsconsumer(%s): nil nats conn", c.Name)
	}
	return nil
}

// floorMonitor is the single monitor this consumer polls: the one named on
// the Config, or the one its Retry carries. validate has already rejected two
// different ones.
func (c Config) floorMonitor() *FloorMonitor {
	if c.FloorMonitor != nil {
		return c.FloorMonitor
	}
	if c.Retry != nil {
		return c.Retry.Monitor()
	}
	return nil
}

// schedule is this consumer's retry timing as plain values: the server ladder
// it runs, and the client-side expectations its Retry holds about that ladder.
func (c Config) schedule() Schedule {
	s := Schedule{
		ServerBackOff: c.BackOff,
		MaxDeliver:    max(c.EffectiveMaxDeliver(), 0), // unlimited reads as "no terminal branch"
		AckWait:       c.EffectiveAckWait(),
	}
	if c.Retry != nil {
		exp := c.Retry.expectations()
		s.CaptureReserve, s.MaxTimeToDeadLetter = exp.CaptureReserve, exp.MaxTimeToDeadLetter
		s.RecoverBy, s.FloorAge = exp.RecoverBy, exp.FloorAge
	}
	return s
}

// checkAgainstStream re-runs the schedule check with the stream's retention
// filled in, which [Config.validate] cannot know: a ladder that outlives
// max_age never reaches its own dead-letter branch, because the stream
// discards the message first. That is silent data loss dressed as a retry
// policy, and it is only visible with both halves in hand.
//
// A stream this cannot read is an error, not a pass. That distinction is the
// whole value of the check: it exists to stop a consumer whose ladder outlives
// retention from starting, so answering "fine" whenever the retention is
// unknown removes the protection in exactly the case where nothing else
// supplies it. Reading the stream and creating the consumer are separate
// JetStream API subjects ($JS.API.STREAM.INFO.> and $JS.API.CONSUMER.>), so a
// credential can be able to do the second and not the first — and then a
// swallowed error means the invalid ladder starts and the source expires the
// message before capture, which is the ENT-1492 loss this check promises to
// prevent.
//
// The legitimate case still rides out, but through the classifier rather than
// through a blanket pass: a stream that does not exist yet — the
// declarative-provisioning race — surfaces as [jetstream.ErrStreamNotFound],
// which [isRetryableStartError] already treats as retryable, so [Run] keeps
// waiting for the stream to appear exactly as before. A denied
// STREAM.INFO publish gets no reply and times out, which is retryable too: the
// consumer never starts, [Run] logs the failure on every attempt, and the safe
// outcome is a consumer that is loudly absent rather than quietly unchecked.
func (c Config) checkAgainstStream(ctx context.Context, js jetstream.JetStream) error {
	if c.Retry == nil && len(c.BackOff) == 0 {
		return nil
	}
	// js.Stream fetches STREAM.INFO to build the handle, so the config is
	// already in hand — a second Info call would be one more round trip and one
	// more failure mode on the startup path.
	stream, err := js.Stream(ctx, c.Stream)
	if err != nil {
		return fmt.Errorf("jsconsumer(%s): read stream %q to check the ladder against its retention: %w", c.Name, c.Stream, err)
	}
	info := stream.CachedInfo()
	if info == nil {
		return fmt.Errorf("jsconsumer(%s): stream %q returned no config to check the ladder against its retention", c.Name, c.Stream)
	}
	sched := c.schedule()
	sched.StreamMaxAge = info.Config.MaxAge
	if err := sched.Err(); err != nil {
		return fmt.Errorf("jsconsumer(%s): %w", c.Name, err)
	}
	return nil
}

func (c Config) tracer() trace.Tracer {
	if c.Tracer == nil {
		return otel.Tracer("github.com/entireio/go-nuts/jsconsumer")
	}
	return c.Tracer
}

func (c Config) logger() *slog.Logger {
	if c.Logger == nil {
		return slog.Default()
	}
	return c.Logger
}

// isShutdownConsumeErr reports whether a consume error is the benign result
// of the connection going away during shutdown. [nuts.IsShutdownFetchErr]
// covers the core nats.go sentinels, but the jetstream consume loop surfaces
// its OWN [jetstream.ErrConnectionClosed] — a distinct value that wraps
// neither — so it must be matched separately or a clean rollout drain still
// logs a warning (the COR-923 noise this suppression exists to remove). As
// with the root classifier, it is only "clean" when ctx is already done; a
// mid-run connection loss is a genuine fault worth logging.
func isShutdownConsumeErr(ctx context.Context, err error) bool {
	return nuts.IsShutdownFetchErr(ctx, err) ||
		(ctx.Err() != nil && errors.Is(err, jetstream.ErrConnectionClosed))
}

// Runner is a live consume loop. Stop halts it and is idempotent.
type Runner struct {
	cc jetstream.ConsumeContext
	// closed is cc.Closed(), captured while the subscription is live (the
	// same channel is returned on every call, so capturing once avoids any
	// post-Stop race) — it closes when the consume loop has fully wound
	// down, including an in-flight handler.
	closed <-chan struct{}
	// watcherDone closes when Start's context-cancellation watcher exits. It is
	// intentionally internal: callers synchronize on Stop, while tests pin that
	// an explicit Stop does not retain a goroutine until the parent context ends.
	watcherDone <-chan struct{}
	// pollDone closes when the Config.Retry ack-floor poll exits; nil when no
	// breaker is armed. Stop joins it, so the connection the poll reads
	// through is safe to drain the moment Stop returns.
	pollDone <-chan struct{}
	stop     sync.Once
}

// Stop halts the consume loop and blocks until it has fully wound down —
// including an in-flight handler — so a caller may tear down what handlers
// use (stores, publishers, the NATS connection) the moment it returns: the
// cancel → join → drain shutdown ordering (COR-923). Safe on a nil or
// never-Started Runner, idempotent, and safe for concurrent use — an
// explicit Stop can race the context-cancel stop armed by Start. Must not be
// called from inside the handler; it would deadlock waiting on itself.
func (r *Runner) Stop() {
	if r == nil || r.cc == nil {
		return
	}
	r.stop.Do(r.cc.Stop)
	<-r.closed
	if r.pollDone != nil {
		<-r.pollDone
	}
}

// Start creates/updates the durable consumer on nc and begins delivering
// messages to onMsg, returning a Runner that Stops when ctx is cancelled. The
// stream must already exist (provisioned declaratively); callers whose cells
// opt in per-stream gate Start behind that opt-in so a cell without the stream
// doesn't error at CreateOrUpdateConsumer.
//
// Consume errors are logged at Warn, except a drain/close during shutdown —
// both the core nats.go sentinels ([nuts.IsShutdownFetchErr]) and jetstream's
// own connection-closed error — which is a clean exit rather than a fault.
func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
	if err := cfg.validate(nc, onMsg); err != nil {
		return nil, err
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
	}
	if err := cfg.checkAgainstStream(ctx, js); err != nil {
		return nil, err
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
		Durable:           cfg.Durable,
		AckPolicy:         jetstream.AckExplicitPolicy,
		AckWait:           cfg.EffectiveAckWait(),
		MaxDeliver:        cfg.EffectiveMaxDeliver(),
		FilterSubject:     cfg.FilterSubject,
		FilterSubjects:    cfg.FilterSubjects,
		InactiveThreshold: cfg.InactiveThreshold,
		MaxAckPending:     cfg.MaxAckPending,
		// Always sent, so an update carries it — and so a nil CLEARS whatever
		// ladder the durable had, leaving AckWait as the schedule. That is
		// why a declaratively-managed ladder cannot simply be omitted here:
		// see Config.BackOff.
		BackOff: cfg.BackOff,
	})
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
	}
	consumeOpts := []jetstream.PullConsumeOpt{jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, cerr error) {
		if isShutdownConsumeErr(ctx, cerr) {
			return
		}
		cfg.logger().WarnContext(ctx, cfg.Name+": consume error", slog.Any("error", cerr))
	})}
	switch {
	case cfg.KeepInProgress:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(1))
	case cfg.MaxMessages > 0:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(cfg.MaxMessages))
	}
	cc, err := cons.Consume(onMsg, consumeOpts...)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
	}
	watcherDone := make(chan struct{})
	r := &Runner{cc: cc, closed: cc.Closed(), watcherDone: watcherDone}
	if cfg.Retry != nil {
		cfg.Retry.attach(cfg.Name, cfg.logger())
	}
	if mon := cfg.floorMonitor(); mon != nil {
		mon.attach(cons, cfg.Name, cfg.logger())
		pollDone := make(chan struct{})
		r.pollDone = pollDone
		go func() {
			defer close(pollDone)
			mon.pollFloor(ctx, r.closed)
		}()
	}
	go func() {
		defer close(watcherDone)
		select {
		case <-ctx.Done():
			r.Stop()
		case <-r.closed:
		}
	}()
	return r, nil
}

// isRetryableStartError classifies the narrow set of failures that can become
// healthy without changing Config or replacing nc. Everything else returns to
// the owner so a bad deployment cannot stay alive indefinitely with no
// consumer. Unknown server-side 5xx responses are retried, except known
// permanent JetStream configuration/account errors whose API happens to use a
// 5xx status.
func isRetryableStartError(err error) bool {
	if errors.Is(err, jetstream.ErrStreamNotFound) ||
		errors.Is(err, nats.ErrNoResponders) ||
		errors.Is(err, nats.ErrTimeout) ||
		errors.Is(err, nats.ErrDisconnected) {
		return true
	}

	var jsErr jetstream.JetStreamError
	if !errors.As(err, &jsErr) || jsErr.APIError() == nil {
		return false
	}
	apiErr := jsErr.APIError()
	switch apiErr.ErrorCode { //nolint:exhaustive // unrecognized 5xx codes are deliberately retryable; all other unknown codes fail closed
	case jetstream.JSErrCodeBadRequest,
		jetstream.JSErrCodeConsumerCreate,
		jetstream.JSErrCodeConsumerNameExists,
		jetstream.JSErrCodeMaximumConsumersLimit,
		jetstream.JSErrCodeJetStreamNotEnabledForAccount,
		jetstream.JSErrCodeJetStreamNotEnabled,
		jetstream.JSErrCodeConsumerAlreadyExists,
		jetstream.JSErrCodeDuplicateFilterSubjects,
		jetstream.JSErrCodeOverlappingFilterSubjects,
		jetstream.JSErrCodeConsumerEmptyFilter,
		jetstream.JSErrCodeConsumerExists:
		return false
	default:
		return apiErr.Code >= 500
	}
}

// Retry envelope for [Run]'s supervision: exponential from runRetryInitial
// doubling to runRetryMax, reset once a consume loop survives longer than the
// max. Package vars (not consts) so tests can compress the schedule.
var (
	runRetryInitial = time.Second
	runRetryMax     = 30 * time.Second
)

// Run supervises the consume loop [Start] builds. Where Start is one-shot —
// an error at consumer creation is returned, and a consume loop that closes
// underneath the caller (consumer deleted on the server, subscription
// invalidated) stays closed — Run retries both with exponential backoff
// (runRetryInitial doubling to runRetryMax, reset after a loop that outlives
// the max). In particular a stream that is not provisioned yet at boot — the
// declarative-provisioning race — is a retry, not a crash.
//
// Run blocks until ctx is cancelled, then joins the live loop (including an
// in-flight handler, see [Runner.Stop]) before returning, so it composes with
// the cancel → join → drain shutdown ordering as the body of a supervised
// goroutine:
//
//	g.Go(func(ctx context.Context) {
//		if err := jsconsumer.Run(ctx, nc, cfg, onMsg); err != nil {
//			log.Error("consumer config rejected", "error", err)
//		}
//	})
//
// Local configuration errors and permanent server responses (invalid consumer
// configuration, authorization/account setup) can never succeed on retry and
// are returned immediately. A missing declarative stream, temporary transport
// failure, or unknown server-side 5xx response remains supervised. A nil return
// means a clean, ctx-driven exit.
func Run(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) error {
	if err := cfg.validate(nc, onMsg); err != nil {
		return err
	}
	delay := runRetryInitial
	for {
		// Each attempt gets a child context so the cancel-watcher goroutine
		// Start arms is released when the attempt dies, instead of one
		// accumulating per recreate for the life of the process.
		attemptCtx, cancelAttempt := context.WithCancel(ctx)
		r, err := Start(attemptCtx, nc, cfg, onMsg)
		if err != nil {
			cancelAttempt()
			if ctx.Err() != nil {
				return nil //nolint:nilerr // a Start error during shutdown is a clean, ctx-driven exit, not a fault to report
			}
			if !isRetryableStartError(err) {
				return err
			}
			cfg.logger().WarnContext(ctx, cfg.Name+": start consumer failed; retrying",
				slog.Any("error", err), slog.Duration("retry_in", delay))
		} else {
			started := time.Now()
			select {
			case <-ctx.Done():
				r.Stop()
				cancelAttempt()
				return nil
			case <-r.closed:
				// Join before recreating, not just cancel: the attempt's
				// ack-floor poll may still be in an in-flight consumer-info
				// request against the OLD consumer, and the next Start attaches
				// the same monitor to a new one. Without the join that reply
				// can land after the reattach and overwrite fresh state with
				// stale. Stop is cheap here — the loop has already closed.
				r.Stop()
				cancelAttempt()
				if ctx.Err() != nil {
					return nil //nolint:nilerr // the loop closing during shutdown is the expected wind-down, not a fault
				}
				// A loop that ran long enough to be called healthy earns a
				// fresh envelope; a flapping one keeps escalating.
				if time.Since(started) >= runRetryMax {
					delay = runRetryInitial
				}
				cfg.logger().WarnContext(ctx, cfg.Name+": consume loop closed; recreating",
					slog.Duration("retry_in", delay))
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case <-time.After(delay):
		}
		delay = min(delay*2, runRetryMax)
	}
}

// Process runs the per-message prologue shared by every consumer: open the
// consumer span (re-parented to the producer across the NATS hop), decode the
// payload, and on a decode error record it, log "<Name>: decode <Stream>;
// term", invoke onUndecodable (so the caller bumps its own drop metric with
// its own attributes), and Term the message — a poison payload won't decode on
// redelivery. On success it invokes handle with the span-enriched context, the
// live span (for RecordError/SetStatus on the business error paths), the
// message, and the decoded event; with Config.KeepInProgress set, an AckWait
// heartbeat runs for the duration

content.content:
// was failing alongside the blocker rather than being it (bounded to one per
// stall window, and the copy is replayable — see [Retry]). Use the monitor
// alone and it is just the health signal, leaving the quarantine decision to
// the adopter.
//
// Lifted from entire-api's internal/jsconsumer (COR-929), folding in the
// module's shutdown classification ([nuts.IsShutdownFetchErr] gates the
// consume-error log so a drain during rollout isn't reported as a fault,
// COR-923) and an optional [natsmsg.KeepInProgress] heartbeat for consumers
// whose handlers legitimately outrun AckWait.
package jsconsumer

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entireio/go-nuts"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	// DefaultAckWait is how long JetStream waits for an ack before redelivery
	// when Config.AckWait is zero — comfortably longer than an RPC round-trip
	// plus a DB upsert, short enough that a stuck message redelivers promptly.
	DefaultAckWait = 30 * time.Second
	// DefaultMaxDeliver caps redelivery before JetStream stops redelivering a
	// message when Config.MaxDeliver is zero.
	DefaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its
// existing on-server filter form exactly.
type Config struct {
	Stream         string        // JetStream stream to bind (must already exist)
	Durable        string        // durable consumer name, stable across restarts
	FilterSubject  string        // set this OR FilterSubjects
	FilterSubjects []string      // set this OR FilterSubject
	AckWait        time.Duration // 0 → DefaultAckWait (see EffectiveAckWait)
	MaxDeliver     int           // 0 → DefaultMaxDeliver (see EffectiveMaxDeliver)
	SpanName       string        // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string        // short consumer name, used as the log prefix

	// InactiveThreshold mirrors jetstream.ConsumerConfig.InactiveThreshold:
	// how long the durable may go without an active subscription before the
	// server deletes it; zero means never (the JetStream default for
	// durables) UNLESS the stream sets ConsumerLimits.InactiveThreshold — see
	// the note below. Consumers on interest-retention streams set this so a
	// decommissioned durable stops pinning every message it would have
	// received, instead of holding them until the stream's MaxAge.
	InactiveThreshold time.Duration

	// MaxAckPending mirrors jetstream.ConsumerConfig.MaxAckPending: the
	// server-side cap on deliveries outstanding un-acked across ALL replicas
	// sharing the durable; zero uses the server default (1000), or the stream's
	// ConsumerLimits.MaxAckPending when it sets one — see the note below.
	// Distinct from MaxMessages below, which caps only this process's
	// client-side buffer.
	//
	// # Stream ConsumerLimits fill in both zeros
	//
	// A stream may carry ConsumerLimits, and the server applies them to any
	// consumer that left the matching field zero. So on such a stream neither
	// zero above means what it says: this scaffold's consumers inherit the
	// STREAM's MaxAckPending instead of 1000, and — the consequential one — an
	// InactiveThreshold instead of never, which gives the durable a deletion
	// timer nobody here asked for. A durable deleted that way is recreated from
	// the stream's DeliverPolicy (all, by default) and replays the retained
	// backlog, so the cost of the surprise is a replay, not just a gap.
	//
	// Set both explicitly on a stream with ConsumerLimits, and read the
	// durable's STORED config rather than assuming either field above is what is
	// running. Requests that leave them unset are also what pedantic-mode
	// clients reject outright (NACK's controller drives fleet Consumer CRs that
	// way), so a config this scaffold applies quietly can fail to reconcile in
	// the cluster. Measured in internal/brokersemantics
	// (TestStreamConsumerLimitsAreInheritedBySilentConsumers).
	MaxAckPending int

	// BackOff mirrors jetstream.ConsumerConfig.BackOff: the redelivery
	// ladder, one delay per redelivery, applied in place of AckWait. The
	// server owns redelivery — this is the one schedule, and [Retry] defers to
	// it by leaving a failed delivery untouched rather than running a
	// competing one client-side. JetStream
	// repeats the last rung once the array runs out, so a short list under a
	// larger MaxDeliver is not a short ladder.
	//
	// Setting it alongside Retry is the intended combination. Its coherence —
	// total time to the dead-letter branch, agreement with AckWait, rung count
	// against MaxDeliver — is checked at Start through [Schedule], the same
	// function fleet CI runs over a rendered NACK Consumer CR.
	//
	// Leaving it nil is a choice, not a default: the broker still redelivers,
	// on AckWait, so the effective ladder becomes AckWait repeated up to
	// MaxDeliver. [Schedule] models it that way and holds it to the same
	// bounds, which is usually how an unset BackOff gets caught — an AckWait
	// sized for one RPC makes a fast, tight retry loop, and one sized for a
	// slow handler makes a very long one.
	//
	// Start always sends this value to CreateOrUpdateConsumer, so a nil also
	// CLEARS any ladder already on the durable. A consumer whose ladder is
	// managed declaratively therefore cannot just omit it here — that erases
	// the managed ladder on every start. Declarative management needs a
	// bind-only mode that skips consumer creation, which does not exist yet;
	// until it does, the app states the ladder here.
	BackOff []time.Duration

	// Retry is where this consumer's retries END: dead-letter capture, then
	// settle, plus — when its RetryConfig names a FloorMonitor — the
	// experimental floor-age circuit breaker. It does NOT schedule
	// redelivery; BackOff above does. When set, [Process] dead-letters an
	// undecodable payload instead of Terming it, and the whole schedule
	// (ladder, AckWait, MaxDeliver, and this Retry's expectations of them) is
	// validated together at Start. Its MaxDeliver must equal
	// EffectiveMaxDeliver().
	//
	// Handlers reach it through the closure they build, and call
	// [Retry.Settle] as their one disposition for a failed delivery. Nil
	// leaves disposition entirely to the handler, as before.
	Retry *Retry

	// FloorMonitor runs the durable's ack-floor health signal: [Start] polls
	// it and [Runner.Stop] joins that poll. Set it to publish the stall as a
	// gauge, or to drive a quarantine rule of your own, without adopting the
	// library's automatic breaker.
	//
	// Leave it nil when Retry already carries the monitor — Start uses that
	// one. Naming two different monitors is a Start error: one durable has one
	// ack floor, and one poll loop should read it.
	FloorMonitor *FloorMonitor

	// Tracer opens the per-message consumer span; nil uses the global OTel
	// tracer provider.
	Tracer trace.Tracer
	// Logger receives the scaffold's own log lines (decode-term warnings,
	// consume errors); nil uses slog.Default.
	Logger *slog.Logger

	// KeepInProgress runs a natsmsg.KeepInProgress heartbeat while handle
	// executes, for handlers that legitimately outrun AckWait. The extension
	// is capped, so a wedged handler still redelivers — see
	// natsmsg.KeepInProgress. The heartbeat stops when handle returns; a tick
	// racing the handler's own terminal Ack/Nak/Term is a client-side no-op
	// (nats.go marks the message disposed locally) that halts the heartbeat.
	//
	// Setting this forces the prefetch to one message (see MaxMessages): the
	// heartbeat extends only the delivery the handler holds, so anything
	// buffered behind a long handler would exhaust its AckWait unextended.
	KeepInProgress bool

	// MaxMessages caps how many deliveries the consume loop buffers
	// client-side (jetstream.PullMaxMessages); 0 uses the nats.go default
	// (500). AckWait runs from server delivery into that buffer, not from
	// callback dispatch, and callbacks run serially — so a consumer whose
	// handler can approach AckWait should keep this small or queued
	// deliveries expire and redeliver concurrently to other replicas.
	// KeepInProgress forces it to 1; setting both to conflicting values is a
	// Start error.
	MaxMessages int
}

// EffectiveAckWait is the AckWait actually applied to the JetStream consumer:
// Config.AckWait, or DefaultAckWait when zero. Use it — not the raw field —
// anywhere the real value matters, e.g. wiring a natsmsg.KeepInProgress
// heartbeat by hand (a zero ackWait there is a no-op).
func (c Config) EffectiveAckWait() time.Duration {
	if c.AckWait == 0 {
		return DefaultAckWait
	}
	return c.AckWait
}

// EffectiveMaxDeliver is the MaxDeliver actually applied to the JetStream
// consumer: Config.MaxDeliver, or DefaultMaxDeliver when zero. Use it — not
// the raw field — when building a backoff.Policy for this consumer's
// messages: the two packages read zero differently (here it means "default
// to DefaultMaxDeliver"; on the policy it means unlimited redeliveries, the
// jetstream.ConsumerConfig semantics), so passing a zero Config.MaxDeliver
// through verbatim would make TermOnExhaustion never fire on the broker's
// real final delivery and orphan work-queue messages (COR-762).
func (c Config) EffectiveMaxDeliver() int {
	if c.MaxDeliver == 0 {
		return DefaultMaxDeliver
	}
	return c.MaxDeliver
}

// validate rejects the configuration errors no retry can fix; shared by
// [Start] (one-shot) and [Run] (supervised, which must fail fast on these
// rather than retry them forever).
func (c Config) validate(nc *nats.Conn, onMsg func(jetstream.Msg)) error {
	if c.KeepInProgress && c.MaxMessages > 1 {
		return fmt.Errorf("jsconsumer(%s): KeepInProgress requires MaxMessages <= 1: the heartbeat extends only the in-flight delivery, so %d buffered messages would exhaust AckWait behind a long handler", c.Name, c.MaxMessages)
	}
	if c.Stream == "" {
		return fmt.Errorf("jsconsumer(%s): Stream is required", c.Name)
	}
	if c.Durable == "" {
		// CreateOrUpdateConsumer accepts an empty durable and silently makes
		// an ephemeral, server-named consumer — losing the stable
		// resume-across-restarts behavior this scaffold promises.
		return fmt.Errorf("jsconsumer(%s): Durable is required", c.Name)
	}
	if onMsg == nil {
		return fmt.Errorf("jsconsumer(%s): onMsg is required", c.Name)
	}
	if c.FilterSubject != "" && len(c.FilterSubjects) != 0 {
		return fmt.Errorf("jsconsumer(%s): set FilterSubject or FilterSubjects, not both", c.Name)
	}
	for i, subject := range c.FilterSubjects {
		if subject == "" {
			return fmt.Errorf("jsconsumer(%s): FilterSubjects[%d] is empty", c.Name, i)
		}
	}
	if c.AckWait < 0 {
		return fmt.Errorf("jsconsumer(%s): AckWait must not be negative", c.Name)
	}
	if c.MaxDeliver < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxDeliver must be -1 (unlimited), 0 (default), or positive", c.Name)
	}
	if c.MaxMessages < 0 {
		return fmt.Errorf("jsconsumer(%s): MaxMessages must not be negative", c.Name)
	}
	if c.MaxAckPending < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxAckPending must be -1 (unlimited), 0 (server or stream ConsumerLimits default), or positive", c.Name)
	}
	if c.InactiveThreshold < 0 {
		return fmt.Errorf("jsconsumer(%s): InactiveThreshold must not be negative", c.Name)
	}
	if c.FloorMonitor != nil && c.Retry != nil && c.Retry.Monitor() != nil && c.FloorMonitor != c.Retry.Monitor() {
		return fmt.Errorf("jsconsumer(%s): %w", c.Name, errMonitorConflict)
	}
	if c.Retry != nil && c.Retry.MaxDeliver() != c.EffectiveMaxDeliver() {
		// A policy that disagrees with the broker either never reaches its
		// terminal branch or reaches it early (COR-762) — and with Retry the
		// terminal branch is the DLQ capture, so the disagreement is a lost
		// message rather than a late one.
		return fmt.Errorf("jsconsumer(%s): Retry MaxDeliver is %d but the consumer's is %d: they must match or the dead-letter branch misses the broker's final delivery", c.Name, c.Retry.MaxDeliver(), c.EffectiveMaxDeliver())
	}
	// The whole retry schedule — the server's ladder plus whatever the Retry
	// expects of it — is checked in one place, by the same function fleet CI
	// runs over a rendered Consumer CR and a future bind-only mode will run
	// against the durable's live config. See [Schedule].
	//
	// Only for a consumer that opted into one of them. A durable that carries
	// neither a Retry nor a ladder has nothing here to be coherent about, and
	// must not acquire a new way to fail at startup because this package grew
	// a validator. It runs AFTER the cross-check above so a genuine
	// MaxDeliver mismatch reports as itself rather than as generic
	// incoherence.
	if c.Retry != nil || len(c.BackOff) > 0 {
		if err := c.schedule().Err(); err != nil {
			return fmt.Errorf("jsconsumer(%s): %w", c.Name, err)
		}
	}
	if nc == nil {
		return fmt.Errorf("jsconsumer(%s): nil nats conn", c.Name)
	}
	return nil
}

// floorMonitor is the single monitor this consumer polls: the one named on
// the Config, or the one its Retry carries. validate has already rejected two
// different ones.
func (c Config) floorMonitor() *FloorMonitor {
	if c.FloorMonitor != nil {
		return c.FloorMonitor
	}
	if c.Retry != nil {
		return c.Retry.Monitor()
	}
	return nil
}

// schedule is this consumer's retry timing as plain values: the server ladder
// it runs, and the client-side expectations its Retry holds about that ladder.
func (c Config) schedule() Schedule {
	s := Schedule{
		ServerBackOff: c.BackOff,
		MaxDeliver:    max(c.EffectiveMaxDeliver(), 0), // unlimited reads as "no terminal branch"
		AckWait:       c.EffectiveAckWait(),
	}
	if c.Retry != nil {
		exp := c.Retry.expectations()
		s.CaptureReserve, s.MaxTimeToDeadLetter = exp.CaptureReserve, exp.MaxTimeToDeadLetter
		s.RecoverBy, s.FloorAge = exp.RecoverBy, exp.FloorAge
	}
	return s
}

// checkAgainstStream re-runs the schedule check with the stream's retention
// filled in, which [Config.validate] cannot know: a ladder that outlives
// max_age never reaches its own dead-letter branch, because the stream
// discards the message first. That is silent data loss dressed as a retry
// policy, and it is only visible with both halves in hand.
//
// A stream this cannot read is an error, not a pass. That distinction is the
// whole value of the check: it exists to stop a consumer whose ladder outlives
// retention from starting, so answering "fine" whenever the retention is
// unknown removes the protection in exactly the case where nothing else
// supplies it. Reading the stream and creating the consumer are separate
// JetStream API subjects ($JS.API.STREAM.INFO.> and $JS.API.CONSUMER.>), so a
// credential can be able to do the second and not the first — and then a
// swallowed error means the invalid ladder starts and the source expires the
// message before capture, which is the ENT-1492 loss this check promises to
// prevent.
//
// The legitimate case still rides out, but through the classifier rather than
// through a blanket pass: a stream that does not exist yet — the
// declarative-provisioning race — surfaces as [jetstream.ErrStreamNotFound],
// which [isRetryableStartError] already treats as retryable, so [Run] keeps
// waiting for the stream to appear exactly as before. A denied
// STREAM.INFO publish gets no reply and times out, which is retryable too: the
// consumer never starts, [Run] logs the failure on every attempt, and the safe
// outcome is a consumer that is loudly absent rather than quietly unchecked.
func (c Config) checkAgainstStream(ctx context.Context, js jetstream.JetStream) error {
	if c.Retry == nil && len(c.BackOff) == 0 {
		return nil
	}
	// js.Stream fetches STREAM.INFO to build the handle, so the config is
	// already in hand — a second Info call would be one more round trip and one
	// more failure mode on the startup path.
	stream, err := js.Stream(ctx, c.Stream)
	if err != nil {
		return fmt.Errorf("jsconsumer(%s): read stream %q to check the ladder against its retention: %w", c.Name, c.Stream, err)
	}
	info := stream.CachedInfo()
	if info == nil {
		return fmt.Errorf("jsconsumer(%s): stream %q returned no config to check the ladder against its retention", c.Name, c.Stream)
	}
	sched := c.schedule()
	sched.StreamMaxAge = info.Config.MaxAge
	if err := sched.Err(); err != nil {
		return fmt.Errorf("jsconsumer(%s): %w", c.Name, err)
	}
	return nil
}

func (c Config) tracer() trace.Tracer {
	if c.Tracer == nil {
		return otel.Tracer("github.com/entireio/go-nuts/jsconsumer")
	}
	return c.Tracer
}

func (c Config) logger() *slog.Logger {
	if c.Logger == nil {
		return slog.Default()
	}
	return c.Logger
}

