func newTestRetry(t *testing.T, mutate func(*RetryConfig)) (*Retry, *fakeDLQ) {
	t.Helper()
	pub := &fakeDLQ{}
	cfg := testRetryConfig(pub)
	if mutate != nil {
		mutate(&cfg)
